const fs = require("fs");
const zlib = require("zlib");
const path = require("path");

const buf = fs.readFileSync(path.join(process.env.TEMP, "opencode", "hireloop-fig", "canvas.fig"));
const outDir = path.join(process.env.TEMP, "opencode", "fig-chunks");
fs.mkdirSync(outDir, { recursive: true });

// Scan for possible zlib (0x78) or raw-deflate starts and try inflating
let saved = 0;
for (let i = 0; i < buf.length - 2 && saved < 400; i++) {
  const b0 = buf[i];
  if (b0 !== 0x78) continue;
  const b1 = buf[i + 1];
  // common zlib header combos
  const ok = [0x01, 0x5e, 0x9c, 0xda, 0x5d].includes(b1);
  if (!ok) continue;
  try {
    const infl = zlib.inflateSync(buf.subarray(i + 2));
    const f = path.join(outDir, `z_${i.toString(16)}.bin`);
    fs.writeFileSync(f, infl);
    saved++;
    i += 256; // skip ahead past this big stream
  } catch (e) {
    // try raw deflate too
    try {
      const infl = zlib.inflateRawSync(buf.subarray(i));
      const f = path.join(outDir, `r_${i.toString(16)}.bin`);
      fs.writeFileSync(f, infl);
      saved++;
      i += 256;
    } catch (e2) {}
  }
}
console.log("saved", saved);

