const fs = require("fs");
const zlib = require("zlib");
const path = require("path");

const buf = fs.readFileSync(process.argv[2]);
const text = buf.toString("latin1");

// find long printable runs (>=4) that contain letters mostly
const words = [];
const re = /[\x20-\x7E]{4,200}/g;
let m;
while ((m = re.exec(text)) !== null) {
  const s = m[0];
  // heuristic: contains common English/design keywords
  if (/(job|Home|nav|Nav|button|Button|header|Header|logo|Logo|menu|Menu|login|Login|sign|Sign|price|Price|compan|Compan|CVP|seeker|Seeker|recruiter|Recruiter|color|Color|text|Text|frame|Frame|button)/i.test(s)) {
    words.push({ i: m.index, s: s.slice(0, 160) });
    if (words.length > 200) break;
  }
}
console.log(JSON.stringify(words, null, 1).slice(0, 6000));

const fs = require("fs");
const zlib = require("zlib");

const buf = fs.readFileSync(process.argv[2]);
const targets = /(POST A JOB|BROWSE JOBS|PRICING|NAVBAR|HEADER|HIRELOOP|SEEKER|RECRUITER|SIGN UP|LOG IN)/i;
const limit = process.argv[3] ? Number(process.argv[3]) : buf.length - 2;
const step = process.argv[4] ? Number(process.argv[4]) : 1;

let attempts = 0;
let best = null;
for (let i = 0; i < limit; i += step) {
  try {
    attempts++;
    const out = zlib.inflateRawSync(buf.subarray(i));
    if (out.length > 1000) {
      const ascii = out.toString("latin1").replace(/[^\x20-\x7E]+/g, " ");
      const printable = (ascii.match(/[\x20-\x7E]/g) || []).length / ascii.length;
      if (targets.test(ascii)) {
        console.log("HIT at", i.toString(16), "len", out.length);
        const m = ascii.match(/.{0,60}(?:JOB|BROWSE|PRICING|NAVBAR|HIRELOOP|SEEKER|RECRUITER|SIGN|LOG).{0,60}/gi);
        console.log((m || []).slice(0, 10).join("\n"));
        fs.writeFileSync(process.argv[2] + `.hit_${i.toString(16)}.bin`, out);
        best = i;
      }
    }
  } catch (e) {}
  if (i % 500000 === 0) console.log("progress", i, "attempts", attempts);
}
console.log("done attempts", attempts);

const fs = require("fs");
const zlib = require("zlib");

const buf = fs.readFileSync(process.argv[2]);
const pos = { i: 0 };

function tryStream(off) {
  return new Promise((resolve) => {
    const out = [];
    let outLen = 0;
    let consumed = 0;
    const dec = zlib.createInflateRaw();
    dec.on("data", (d) => { out.push(d); outLen += d.length; });
    const finish = (ok) => {
      try { dec.close(); } catch {}
      resolve({ ok, out: Buffer.concat(out), consumed, outLen });
    };
    dec.on("end", () => finish(true));
    dec.on("error", (e) => { consumed = dec.bytesWritten; finish(false); });
    // feed in small chunks so we can track consumed bytes on error
    const CHUNK = 4096;
    dec.on("data", () => {}); // ensure flow
    let src = off;
    const pump = () => {
      while (src < buf.length) {
        const piece = buf.subarray(src, src + CHUNK);
        const before = dec.bytesWritten;
        dec.write(piece);
        src += piece.length;
        if (dec.writableNeedDrain) {
          dec.once("drain", pump);
          return;
        }
      }
      dec.end();
    };
    dec.on("error", () => {});
    pump();
    // track consumed on error: bytes accepted by decoder = zlib internal count
    dec.once("close", () => {});
    dec.bytesReadTotal = () => src;
    // simpler: window size trick not available; use end/error to resolve
  });
}

(async () => {
  let off = 0;
  // find header magic
  const head = buf.subarray(0, 16).toString("latin1");
  console.log("header:", JSON.stringify(head));
  off = 10; // skip "fig-kiwij" + version?
  let index = 0;
  const results = [];
  while (off < buf.length && index < 40) {
    const res = await tryStreamSimple(off, buf);
    if (res.ok && res.outLen > 0) {
      results.push({ off, outLen: res.outLen, compressedLen: res.consumedEnd - off });
      fs.writeFileSync(`${process.argv[2]}_chunk${index}.bin`, res.out);
      console.log(`chunk ${index}: off=${off} compLen=${res.consumedEnd - off} outLen=${res.outLen}`);
      off = res.consumedEnd;
      // skip any trailing padding to next likely stream start
      index++;
    } else {
      off++;
      // don't brute more than 64k of gaps
      if (index > 0 && off > results[results.length - 1].consumedEnd + 65536) break;
    }
  }
  console.log("walk done");
})().catch(e => console.error("fatal", e));

// simpler streaming approach: inflate from off; consumed end tracked via error offset approximation
function tryStreamSimple(off, buf) {
  return new Promise((resolve) => {
    let chunks = [];
    let totalOut = 0;
    const infl = zlib.createInflateRaw();
    infl.on("data", (d) => { chunks.push(d); totalOut += d.length; });
    infl.on("error", () => resolve({ ok: false, outLen: 0, consumedEnd: off }));
    infl.on("end", () => {
      // consumed = we wrote whole buffer in one go; need actual stream end: re-run
      resolve({ ok: true, out: Buffer.concat(chunks), outLen: totalOut, consumedEnd: findEndApprox });
    });
    let findEndApprox = buf.length;
    infl.write(buf.subarray(off));
    infl.end();
  });
}

const fs = require("fs");
const zlib = require("zlib");

const buf = fs.readFileSync(process.argv[2]);

// Inflate starting at `off`, writing one byte at a time.
// Returns resolved promise with { ok, out, consumed } — consumed = bytes fed until stream 'end' or error.
function tryStream(off) {
  return new Promise((resolve) => {
    const chunks = [];
    let totalOut = 0;
    let fed = 0;
    const infl = zlib.createInflateRaw();
    let done = false;
    infl.on("data", (d) => { chunks.push(d); totalOut += d.length; });
    const finish = (ok) => {
      if (done) return;
      done = true;
      infl.destroy();
      // zlib may over-consume on failure; the true consumed length for a *succesful*
      // stream is exactly `fed` (we stop feeding at 'end')
      resolve({ ok, out: Buffer.concat(chunks), consumed: fed });
    };
    infl.on("end", () => finish(true));
    infl.on("error", () => finish(false));
    const pump = () => {
      while (fed < buf.length - off) {
        infl.write(buf[off + fed] === undefined ? undefined : buf.subarray(off + fed, off + fed + 1));
        fed++;
        if (done) return;
        if (infl.writableNeedDrain) { infl.once("drain", pump); return; }
      }
      infl.end();
    };
    pump();
  });
}

(async () => {
  const head = buf.subarray(0, 24).toString("latin1");
  console.log("header bytes:", JSON.stringify(head));
  // skip magic "fig-" + 5 bytes? We found schema inflates cleanly from offset 10.
  let off = 10;
  let index = 0;
  const starts = [];
  while (off < buf.length && index < 30) {
    const res = await tryStream(off);
    if (res.ok && res.out.length > 100) {
      const file = `${process.argv[2]}_chunk${index}.bin`;
      fs.writeFileSync(file, res.out);
      const printable = (res.out.toString("latin1").replace(/[^\x20-\x7E\s]+/g, "")).length / res.out.length;
      console.log(`chunk ${index}: start=${off} end=${off + res.consumed} outLen=${res.out.length} printable=${printable.toFixed(2)}`);
      starts.push(off);
      off = off + res.consumed;
      index++;
    } else {
      off++;
      if (index > 0 && off - starts[starts.length - 1] > 65536) { console.log("gap too big, stop"); break; }
    }
  }
  console.log("done, chunks:", index);
})().catch(e => console.error("fatal", e));

