const path = require("path");
const dir = path.join(process.env.TEMP, "opencode", "hireloop-fig");
for (const i of [1, 2, 3, 4, 5, 7, 8, 9, 11, 12, 13, 14, 15, 17, 19, 20, 21, 22]) {
  const f = path.join(dir, "canvas.fig_chunk" + i + ".bin");
  if (!fs.existsSync(f)) continue;
  const b = fs.readFileSync(f);
  const t = b.toString("latin1").replace(/[^\x20-\x7E]+/g, "\u00b7");
