        { id: 'companies', name: 'Companies', icon: Building2, url: '/dashboard/admin/companies' },
        { id: 'jobs', name: 'Jobs', icon: Briefcase, url: '/dashboard/admin/jobs' },
        { id: 'payments', name: 'Payments', icon: Banknote, url: '/dashboard/admin/payments' },
        { id: 'settings', name: 'Settings', icon: Settings, url: '/dashboard/admin/settings' },
    ],
}

function initialsOf(name: string) {
    return name
        .split(/\s+/)
        .filter(Boolean)
        .slice(0, 2)
        .map((part) => part[0]!.toUpperCase())
        .join('') || 'HL'
}

/* The avatar + name card shown in the header (seeker/recruiter) or footer (admin) */
function UserCard({
    name,
    subtitle,
    image,
    badge,
    className,
}: {
    name: string
    subtitle: string
    image?: string | null
    badge?: string
    className?: string
}) {
    return (
        <div
            className={
                'mx-3 flex items-center gap-3 rounded-xl border bg-card/60 p-3 ' + (className ?? '')
            }
        >
            <Avatar className="size-9">
                {image ? <AvatarImage src={image} alt={name} /> : null}
                <AvatarFallback className="text-xs">{initialsOf(name)}</AvatarFallback>
            </Avatar>
            <div className="flex min-w-0 flex-col gap-1">
                <span className="truncate text-sm font-medium text-foreground">{name}</span>
                <span className="text-xs text-muted-foreground">{subtitle}</span>
                {badge ? (
                    <Badge className="w-fit bg-primary/15 text-primary hover:bg-primary/15">
                        {badge}
                    </Badge>
                ) : null}
            </div>
        </div>
    )
}

export function DashboardSidebar() {
    const { data: session, isPending } = useSession()
    const role = (session?.user.role || 'seeker') as DashboardRole
    const pathname = usePathname()
    const router = useRouter()

    const isActive = (url: string) =>
        pathname === url || pathname.startsWith(url + '/')

    const handleLogout = async () => {
        await signOut()
        router.push('/')
    }

    const items = menuItemsByRole[role]

    return (
        <Sidebar>
            <SidebarHeader className="flex flex-col gap-4">
                <div className="px-4 pt-4">
                    <SiteLogo />
                </div>

                {/* Seeker & Recruiter: user card under the logo. Admin shows it in the footer instead. */}
                {role !== 'admin' && !isPending && (
                    role === 'seeker' ? (
                        <UserCard
                            name={session?.user.name || 'Seeker Portal'}
                            subtitle="Professional Tier"
                            image={session?.user.image}
                        />
                    ) : (
                        <UserCard
                            name={session?.user.name || 'Recruiter Portal'}
                            subtitle="Recruiter"
                            image={session?.user.image}
                            badge="Premium account"
                        />
                    )
                )}
            </SidebarHeader>

            <SidebarContent>
                <SidebarGroup>
                    {role === 'admin' && <SidebarGroupLabel>Admin Console</SidebarGroupLabel>}
                    <SidebarMenu>
                        {!isPending &&
                            items.map((item) => (
                                <SidebarMenuItem key={item.id}>
                                    <SidebarMenuButton
                                        isActive={isActive(item.url)}
                                        render={<Link href={item.url} />}
                                    >
                                        <item.icon />
                                        <span>{item.name}</span>
                                    </SidebarMenuButton>
                                </SidebarMenuItem>
                            ))
                        }
                    </SidebarMenu>
                </SidebarGroup>
            </SidebarContent>

            <SidebarFooter className="flex flex-col gap-2 p-2">
                {role === 'seeker' && (
                    <Button
                        nativeButton={false}
                        render={<Link href="/dashboard/seeker/settings" />}
                        className="w-full justify-center rounded-lg bg-foreground text-background hover:bg-foreground/90"
                    >
                        Post Resume
                    </Button>
                )}

                {role === 'admin' && !isPending && (
                    <UserCard
                        name={session?.user.name || 'Admin'}
                        subtitle="Super Admin"
                        image={session?.user.image}
                    />
                )}

                <SidebarMenu>
                    <SidebarMenuItem>
                        <SidebarMenuButton
                            onClick={handleLogout}
                            tooltip="Logout"
                            className="text-muted-foreground hover:text-foreground"
                        >
                            <LogOut />
                            <span>Logout</span>
                        </SidebarMenuButton>
                    </SidebarMenuItem>
                </SidebarMenu>
            </SidebarFooter>
        </Sidebar>
    )
}

